// Select the first persona for focused research
const analysis = JSON.parse($json.choices[0].message.content);
const selectedPersona = analysis.ideal_customers[0];

return {
  selected_persona: selectedPersona,
  underlying_problem: analysis.underlying_problem,
  meta_problem: analysis.meta_problem,
  research_query: `Find discussions about ${selectedPersona.title} struggling with ${analysis.underlying_problem}. Look for emotional language, frustrations, and exact quotes about their pain points.`
};

values.content:
Persona: {{ $json.selected_persona.title }}
Problem: {{ $json.underlying_problem }}
Context: {{ $json.meta_problem }}

