// Create the mega context prompt for content generation
const productAnalysis = $('product-analysis').first().json.choices[0].message.content;
const researchReport = $('mega-research-report').first().json.choices[0].message.content;
const marketingAngles = $('marketing-angles').first().json.choices[0].message.content;

const megaContext = `# MEGA MARKETING CONTEXT

You are tasked to help me with copywriting tasks using this customer research. Read and understand this context, then wait for content creation instructions.

## PRODUCT ANALYSIS
${productAnalysis}

## CUSTOMER RESEARCH REPORT
${researchReport}

## MARKETING ANGLES
${marketingAngles}

## COPYWRITING GUIDELINES
- Always use customer's exact language and quotes
- Address the deep psychological problems, not surface issues
- Focus on emotional triggers identified in research
- Choose appropriate marketing angles for each content type
- Maintain authenticity by using real customer pain points

I understand the context and am ready for content creation tasks.`;

return {
  mega_context: megaContext,
  ready_for_content: true
};

values.content:
Product: {{ $json.product_name }}
Description: {{ $json.product_description }}
URL: {{ $json.product_url }}
Features: {{ $json.technical_features }}
